// Simple asteroid dodge game targeting canvas with id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // canvas not found
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // ----- Game State -----
  const ship = {
    x: width / 2,
    y: height / 2,
    angle: 0, // radians, 0 points up
    velX: 0,
    velY: 0,
    radius: 10,
  };
  const keys = { ArrowLeft: false, ArrowRight: false, ArrowUp: false };
  const asteroids = [];
  let gameOver = false;
  let spawnTimer = 0;

  // ----- Input -----
  window.addEventListener('keydown', e => { if (keys.hasOwnProperty(e.key)) keys[e.key] = true; });
  window.addEventListener('keyup', e => { if (keys.hasOwnProperty(e.key)) keys[e.key] = false; });

  // ----- Helpers -----
  function rand(min, max) { return Math.random() * (max - min) + min; }
  function distance(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }

  function spawnAsteroid() {
    // spawn on random edge
    const edge = Math.floor(rand(0, 4));
    let x, y, vx, vy;
    const speed = rand(1, 3);
    if (edge === 0) { // top
      x = rand(0, width); y = -20; vx = rand(-1, 1); vy = speed;
    } else if (edge === 1) { // right
      x = width + 20; y = rand(0, height); vx = -speed; vy = rand(-1, 1);
    } else if (edge === 2) { // bottom
      x = rand(0, width); y = height + 20; vx = rand(-1, 1); vy = -speed;
    } else { // left
      x = -20; y = rand(0, height); vx = speed; vy = rand(-1, 1);
    }
    const radius = rand(8, 20);
    asteroids.push({ x, y, vx, vy, radius });
  }

  function update(dt) {
    if (gameOver) return;
    // ship controls
    if (keys.ArrowLeft) ship.angle -= 0.07;
    if (keys.ArrowRight) ship.angle += 0.07;
    if (keys.ArrowUp) {
      const thrust = 0.1;
      ship.velX += Math.sin(ship.angle) * thrust;
      ship.velY -= Math.cos(ship.angle) * thrust;
    }
    // apply friction
    ship.velX *= 0.99; ship.velY *= 0.99;
    // move ship
    ship.x += ship.velX;
    ship.y += ship.velY;
    // wrap around edges
    if (ship.x < 0) ship.x += width;
    if (ship.x > width) ship.x -= width;
    if (ship.y < 0) ship.y += height;
    if (ship.y > height) ship.y -= height;

    // spawn asteroids
    spawnTimer -= dt;
    if (spawnTimer <= 0) { spawnAsteroid(); spawnTimer = rand(0.5, 1.5); }

    // move asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx; a.y += a.vy;
      // remove if far off-screen
      if (a.x < -50 || a.x > width + 50 || a.y < -50 || a.y > height + 50) {
        asteroids.splice(i, 1);
        continue;
      }
      // collision with ship
      if (distance(a.x, a.y, ship.x, ship.y) < a.radius + ship.radius) {
        gameOver = true;
      }
    }
  }

  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(0, -ship.radius);
    ctx.lineTo(ship.radius, ship.radius);
    ctx.lineTo(-ship.radius, ship.radius);
    ctx.closePath();
    ctx.fillStyle = '#0f0';
    ctx.fill();
    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // asteroids
    ctx.fillStyle = '#999';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // ship
    drawShip();
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = (now - last) / 1000; // seconds
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
